def digit_key(x):
    count = [0] * 10
    while x > 0:
        count[x % 10] += 1
        x //= 10
    k = 0
    for d in range(9, -1, -1):
        for _ in range(count[d]):
            k = k * 10 + d
    return k

def group_by_digits(nums):
    group_of = {}
    groups = []
    for x in nums:
        k = digit_key(x)
        if k not in group_of:
            group_of[k] = len(groups)
            groups.append([])
        groups[group_of[k]].append(x)
    return groups

