static long digitKey(int x) {
    int[] count = new int[10];
    for (; x > 0; x /= 10) count[x % 10]++;
    long k = 0;
    for (int d = 9; d >= 0; d--) {
        for (int c = 0; c < count[d]; c++) k = k * 10 + d;
    }
    return k;
}

static List<List<Integer>> groupByDigits(int[] nums) {
    Map<Long, Integer> groupOf = new HashMap<>();
    List<List<Integer>> groups = new ArrayList<>();
    for (int x : nums) {
        long k = digitKey(x);
        Integer g = groupOf.get(k);
        if (g == null) {
            g = groups.size();
            groupOf.put(k, g);
            groups.add(new ArrayList<>());
        }
        groups.get(g).add(x);
    }
    return groups;
}

