vector<vector<int>> groupByDigits(const vector<int>& nums) {
    unordered_map<long long, int> groupOf;
    vector<vector<int>> groups;
    for (int x : nums) {
        long long k = digitKey(x);
        auto [it, isNew] = groupOf.emplace(k, (int)groups.size());
        if (isNew) groups.emplace_back();
        groups[it->second].push_back(x);
    }
    return groups;
}

