// Writes nums grouped into out (group by group, input order inside each),
// the start of group g at start[g] (start[groups] = n), and returns the number of groups.
int groupByDigits(const int* nums, int n, int* out, int* start) {
    size_t cap = 16;
    while (cap < 2 * (size_t)n) cap <<= 1;
    long long* keys = malloc(cap * sizeof(long long));
    int* gid = malloc(cap * sizeof(int));
    bool* used = calloc(cap, sizeof(bool));
    int* groupOfItem = malloc((n + 1) * sizeof(int));
    int groups = 0;
    for (int j = 0; j < n; j++) {
        long long k = digitKey(nums[j]);
        size_t i = (size_t)(((uint64_t)k * 0x9E3779B97F4A7C15ull) >> 32) & (cap - 1);
        while (used[i] && keys[i] != k) i = (i + 1) & (cap - 1);
        if (!used[i]) {
            used[i] = true;
            keys[i] = k;
            gid[i] = groups++;
        }
        groupOfItem[j] = gid[i];
    }
    for (int g = 0; g <= groups; g++) start[g] = 0;
    for (int j = 0; j < n; j++) start[groupOfItem[j] + 1]++;
    for (int g = 0; g < groups; g++) start[g + 1] += start[g];
    int* fill = malloc((groups + 1) * sizeof(int));
    memcpy(fill, start, (groups + 1) * sizeof(int));
    for (int j = 0; j < n; j++) out[fill[groupOfItem[j]]++] = nums[j];
    free(keys); free(gid); free(used); free(groupOfItem); free(fill);
    return groups;
}
